source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"up": 0, "down": 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            minr, maxr = min(y for y,x in cells), max(y for y,x in cells)
            minc, maxc = min(x for y,x in cells), max(x for y,x in cells)
            shape = {(y-minr, x-minc) for y,x in cells}
            if (maxr-minr, maxc-minc) == (1, 2) and len(cells) == 4:
                if {(0,1),(1,0),(1,1),(1,2)} == shape:
                    counts["up"] += 1
                elif {(0,0),(0,1),(0,2),(1,1)} == shape:
                    counts["down"] += 1
    out = [[0]*6 for _ in range(3)]
    corner_order = ((0,0),(2,0),(0,2),(2,2))
    for n, (r,c) in enumerate(corner_order[:counts["up"]]):
        out[r][c] = 3
    for n, (r,c) in enumerate(corner_order[:counts["down"]]):
        out[r][c+3] = 1
    return out
'''
